function Status({value,L}){const names=statusNames[value];return <span className={`ig-status ig-status-${String(value).toLowerCase()}`}>{names?L(...names):value||'—'}</span>;}
function Table({headers,children,empty,L,className=''}){return <div className={`ig-table-scroll${className.includes('ig-operational-table')?' ig-operational-table-wrap':''}`}><table className={`ig-table ${className}`}><thead><tr>{headers.map((h,i)=><th key={i}>{h}</th>)}</tr></thead><tbody>{empty?<tr><td colSpan={headers.length}><div className="ig-empty">{L('Belum ada data untuk ditampilkan.','No records to display.')}</div></td></tr>:children}</tbody></table></div>;}
function Section({title,description,action,children}){return <section className="ig-panel"><div className="ig-panel-head"><div><h2>{title}</h2>{description&&<p>{description}</p>}</div>{action}</div>{children}</section>;}
function Metric({label,value,caption}){return <article className="ig-metric"><span>{label}</span><strong>{value}</strong><small>{caption}</small></article>;}

function DriverDailySummary({summary,L,fmt,stale}){
 const validDate=typeof summary?.localDate==='string'&&/^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.test(summary.localDate);
 const validDay=validDate&&summary?.timeZone==='Asia/Jakarta';
 const available=!stale&&validDay&&['READY','PARTIAL'].includes(summary?.status);
 const metrics=[['unfinishedTrips',L('Total Ritase belum selesai','Total unfinished trips'),'driver-summary-unfinished'],['completedTrips',L('Total ritase sudah selesai','Total completed trips'),'driver-summary-completed']];
 const caption=L('Hari ini','Today')+' · '+(validDay?summary.localDate:'—')+' · WIB';
 return <div className="ig-driver-summary" data-testid="driver-summary" data-status={available?summary.status:'UNAVAILABLE'} data-local-date={validDay?summary.localDate:undefined} data-time-zone="Asia/Jakarta">
  {metrics.map(([key,title,testId])=>{const value=summary?.[key],ready=available&&summary?.availability?.[key]===true&&Number.isSafeInteger(value)&&value>=0;return <article className="ig-metric" key={key} data-testid={testId+'-card'}>
   <span>{title}</span><strong data-testid={testId} data-value={ready?value:undefined}>{ready?fmt(value,0):'—'}</strong><small>{caption}</small>
   {key==='unfinishedTrips'&&summary?.includeCarryover===true&&<small data-testid="driver-summary-carryover">{L('Termasuk ritase tertunda dari hari sebelumnya','Includes unfinished trips from previous days')}</small>}
   {!ready&&<small className="ig-driver-summary-unavailable">{L('Data harian belum tersedia','Daily data is unavailable')}</small>}
  </article>;})}
 </div>;
}

function FleetStatusSummary({entries,truckCount,L}){
 const known=entries.length>0||truckCount===0;
 const states=[['available',L('Tersedia','Available'),L('Siap untuk dispatch baru','Ready for a new dispatch')],['allocated',L('Dialokasi','Allocated'),L('Antrean serial terikat ke satu dispatch','Serial queue bound to one dispatch')],['busy',L('Sedang bertugas','Busy'),L('Ritase sudah dimulai','A trip has started')],['unavailable',L('Nonaktif','Unavailable'),L('Tidak masuk alokasi otomatis','Excluded from automatic allocation')]];
 return <div className="ig-fleet-state-summary" data-testid="fleet-status-summary">{states.map(([status,label,caption])=><div key={status} data-fleet-count-status={status}><span><i className={`ig-fleet-dot ${status}`}/>{label}</span><b>{known?entries.filter(entry=>entry.status===status).length:'—'}</b><small>{caption}</small></div>)}</div>;
}

