 const source=t=>t.allocations?.length>1?t.allocations.map(a=>`${crusher(a.crusherId)?.code||a.crusherId} / ${pile(a.stockpileId)?.code||a.stockpileId}`).join(' · '):`${t.sourceCrusherCode||crusher(t.crusherId)?.code||t.crusherId||'—'} / ${t.sourceStockpileCode||pile(t.stockpileId)?.code||t.stockpileId||'—'}`;
 const destination=t=>{const location=t.destinationLocationSnapshot?.name||t.destinationLocationName;return t.transferMode==='LAND'||(!t.vesselId&&t.destinationId)?`${location||t.destinationCrusherCode||crusher(t.destinationId||t.destinationCrusherId)?.code||t.destination||t.destinationId||'LAND'} / ${t.destinationStockpileCode||pile(t.destinationStockpileId)?.code||t.destinationStockpileId||'—'}`:`${jetty(t.jettyId)?.code||t.jettyId||'—'} / ${vessel(t.vesselId)?.code||t.vesselId||'—'}${location?' → '+location:''}`;};
 const relevantTrips=role==='driver'?trips.filter(t=>t.assignedDriverUserId===user.id):trips;
 const activeTrips=relevantTrips.filter(t=>!terminal.has(t.status));
 const waitingTrips=activeTrips.filter(t=>!t.truckId),assignedTrips=activeTrips.filter(t=>t.truckId);
