   <div className="ig-demo-notice"><QrCode size={19}/><span><b>{L('Demo transaksi terintegrasi','Integrated transaction demo')}</b> · {L('QR dan bobot adalah data simulasi, bukan pengukuran alat fisik. NetSuite tetap berupa outbox demo, bukan posting ERP terverifikasi.','QR and weights are simulated data, not physical instrument readings. NetSuite remains a demo outbox, not verified ERP posting.')}</span></div>
   {(error||logoutError)&&<div className="ig-alert" role="alert"><span>{tr(error?.text||logoutError)}{error?.uncertain&&<> {L('Status aksi belum pasti. Gunakan Coba ulang agar ID permintaan yang sama dipakai kembali.','The action outcome is uncertain. Use Retry to reuse the same request ID.')}</>}</span>{retry&&<Button disabled={busy} onClick={()=>execute(retry.body,retry.options)}>{L('Coba ulang aksi yang sama','Retry the same action')}</Button>}</div>}
